import {orderPage,mountOrders,placeOrder,setupOrderEvents} from './order-flow.js';
import {business} from './config.js';
import {landingHero} from './landing.js';
import {setupMotion,motionEnabled} from './motion.js';
import {products,categories,money,findProduct,normalizeCart,cartTotal,cartCount,filterProducts,validateCheckout,categoryInfo,priceLabel,amountRange,quoteTotals,lineQuote} from './store.js';

const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>{
  const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4 10-10"/>',leaf:'<path d="M20 4C9 3 3 8 5 15s15 7 15-11Z"/><path d="m4 21 12-12"/>'};
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.arrow}</svg>`;
};
const arrow=icon('arrow');
const brand=`<span class="wordmark">SRI BALAJI<small>BAMBOO WORKS</small></span>`;
let cart=[];
try{cart=normalizeCart(JSON.parse(localStorage.getItem('sbb-cart')||'[]'));}catch{}
let toastTimer;
let shopState={category:'',query:'',sort:'featured'};
let selectedSize='';
let productQuantity=1;
const persistCart=()=>{try{localStorage.setItem('sbb-cart',JSON.stringify(cart));}catch{notify('Your bag is available for this visit. Browser storage is unavailable.');}renderHeader();};
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function photo(p,classes=''){return `<img class="product-photo ${classes}" src="assets/${p.image}" alt="${esc(p.name)}, product photograph" loading="lazy" decoding="async" style="--photo-position:${p.position||'50% 50%'}">`;}
const link=(href,label,cls='button')=>`<a class="${cls}" href="${href}">${label}${arrow}</a>`;
function renderHeader(){
  const route=location.hash.startsWith('#/')?location.hash.slice(1).split('?')[0]:location.pathname;
  $('#header').innerHTML=`<div class="header-inner"><a class="brand" href="/" aria-label="Sri Balaji Bamboo Works home">${brand}</a><nav class="desktop-nav" aria-label="Main navigation">${[['/shop','Shop'],['/collections','Collections'],['/story','Our Story'],['/bulk','Bulk Orders'],['/contact','Contact'],['/orders','My orders']].map(([r,l])=>`<a href="${r}" ${route===r?'aria-current="page"':''}>${l}</a>`).join('')}</nav><div class="header-actions"><button class="motion-toggle" data-motion aria-pressed="true">Motion: On</button><button class="icon-button" data-search aria-label="Search products">${icon('search')}</button><a class="icon-button bag-link" href="/cart" aria-label="Shopping bag, ${cartCount(cart)} items">${icon('bag')}<span class="bag-count">${cartCount(cart)}</span></a><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false" aria-controls="mobile-nav">${icon('menu')}</button></div></div><nav id="mobile-nav" aria-label="Mobile navigation" hidden>${[['/shop','Shop the collection'],['/collections','All nine collections'],['/story','Our Story'],['/bulk','Bulk Orders'],['/contact','Contact'],['/orders','My orders']].map(([r,l])=>`<a href="${r}">${l}${arrow}</a>`).join('')}</nav>`;
}
function renderFooter(){
  $('#footer').innerHTML=`<div class="footer-top container"><div><a class="brand" href="/">${brand}</a><p>Natural texture.<br>Everyday purpose.</p></div><div><h2>Explore</h2><a href="/shop">The collection</a><a href="/collections">Nine collections</a><a href="/story">Our story</a><a href="/bulk">Bulk enquiries</a></div><div><h2>How can we help?</h2><a href="/contact">Contact us</a><a href="/care">Product care & ordering</a><a href="/orders">My orders & payment</a><a href="/owner">Owner sign in</a><a href="/cart">Your shopping bag</a></div><div class="footer-note">${icon('leaf')}<p>Baskets, trays and bamboo materials.<br>Find a form for your everyday.</p></div></div><div class="footer-contact container"><div><h2>Call us directly</h2><a href="tel:+${business.whatsapp.replace(/\D/g,'')}">+91 95914 57484</a></div><div><h2>Email us</h2><a href="mailto:${esc(business.email)}">${esc(business.email)}</a></div></div><div class="footer-bottom container"><span>© ${new Date().getFullYear()} Sri Balaji Bamboo Works</span><span>Owner-supplied prices · INR</span></div>`;
}
function card(p){return `<article class="product-card" data-reveal><a class="product-image-link depth-card" data-depth href="/product/${p.id}" aria-label="View ${esc(p.name)}">${photo(p)}<span class="image-cta">Take a closer look ${arrow}</span>${p.representative?'<span class="photo-tag">Representative photo</span>':''}</a><div class="card-details"><span class="eyebrow">${categoryInfo[p.category].short}</span><a href="/product/${p.id}" class="product-title">${p.name}</a><p class="kn card-kn" lang="kn">${p.nameKn}</p><div class="card-bottom"><span>${priceLabel(p)}${!p.unit?'<small>Unit to confirm</small>':''}</span><a class="icon-button" href="/product/${p.id}" aria-label="View ${esc(p.name)}">${arrow}</a></div></div></article>`;}
function collectionJourney(){return `<section class="collection-journey" aria-label="Explore nine collections"><div class="journey-sticky"><div class="journey-heading"><div><span class="eyebrow">FOLLOW THE WEAVE</span><h2>Nine collections.<br><em>One natural thread.</em></h2></div><p>Scroll to travel through the collection.<br>Choose a chapter to jump ahead.</p><span class="journey-counter" aria-hidden="true">01 / 09</span></div><nav class="journey-nav" aria-label="Collection chapters">${Object.values(categoryInfo).map((c,i)=>`<button data-chapter="${i}" aria-label="Jump to ${c.short}"><span>${String(i+1).padStart(2,'0')}</span>${c.short}</button>`).join('')}</nav><div class="journey-window"><div class="journey-track">${Object.entries(categoryInfo).map(([id,c],i)=>`<article class="journey-panel" id="chapter-${id}"><a class="journey-photo" href="/collections/${id}" aria-label="Explore ${c.name}"><img src="assets/${c.image}" alt="${esc(c.name)} from Sri Balaji Bamboo Works" loading="lazy" decoding="async"><span class="journey-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span></a><div class="journey-copy"><span class="eyebrow">${c.chapter}</span><h3>${c.short}</h3><p class="kn" lang="kn">${c.kn}</p><p>${c.description}</p><span class="collection-count">${products.filter(p=>p.category===id).length} selections</span>${link('/collections/'+id,'Explore '+c.short,'text-link')}</div></article>`).join('')}</div></div><div class="journey-progress" aria-hidden="true"><span></span></div></div></section>`;}
function collections(){return `<section class="page-heading container"><span class="eyebrow">THE COMPLETE COLLECTION</span><h1>Many forms.<br><em>Rooted in everyday life.</em></h1><p>Explore all nine families, with English and Kannada names, detailed product notes and prices supplied by the workshop.</p></section><nav class="collection-index container" aria-label="Jump to a collection">${Object.entries(categoryInfo).map(([id,c])=>`<a href="#collection-${id}" data-scroll="collection-${id}">${c.short} ↘</a>`).join('')}</nav>${Object.entries(categoryInfo).map(([id,c],i)=>`<section id="collection-${id}" class="collection-section container section"><div class="collection-intro"><div><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${c.chapter}</span><h2>${c.name}</h2><p class="kn" lang="kn">${c.kn}</p><p>${c.description}</p></div><div class="collection-guidance"><h3>Choose for your purpose</h3><p>${c.uses}</p><h3>When you enquire</h3><p>${c.ask}</p></div></div><div class="product-grid">${products.filter(p=>p.category===id).map(card).join('')}</div></section>`).join('')}${bulkBand()}`;}

function categoryCard(category,title,subtitle,tile){return `<a class="category-card" href="/collections/${category}">${photo(products.find(p=>p.category===category))}<div><span><h3>${title}</h3><p>${subtitle}</p></span>${arrow}</div></a>`;}
function sectionTitle(eyebrow,title,href='/shop',text='View the collection'){return `<div class="section-title"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div>${link(href,text,'text-link')}</div>`;}
function bulkBand(){return `<section class="bulk-band container"><div><span class="eyebrow">FOR YOUR BUSINESS</span><h2>A little more bamboo?</h2><p>Talk to us about larger quantities and material requirements.</p></div>${link('/bulk','Enquire about bulk orders')}</section>`;}
function home(){return `${landingHero()}<section class="container local-intro"><h2>Bamboo shop in Shidlaghatta, Karnataka</h2><p>Visit Sri Balaji Bamboo Works on Garden Road, Shidlaghatta, Chikkaballapur district. Explore handwoven baskets, traditional Mara trays, hand fans, bamboo poles and ladders, with English and Kannada product names. Confirm sizes, availability and delivery with our workshop before payment.</p><a class="text-link" href="/contact">Contact the workshop →</a></section><section id="workshop-welcome" class="hero workshop-welcome"><div class="hero-copy"><span class="eyebrow">SHIDLAGHATTA, KARNATAKA · SRI BALAJI BAMBOO WORKS</span><h2>A familiar craft.<br><em>A thousand uses.</em></h2><p class="kn hero-kn" lang="kn">ನಿತ್ಯದ ಬದುಕಿಗೆ ಬಿದಿರಿನ ಸೊಬಗು.</p><p>From the curve of a Butti to the weave of a Mara. Discover useful, characterful forms from our workshop.</p><div class="hero-buttons">${link('/shop','Shop the collection')}${link('/collections','Meet every collection','text-link')}</div><span class="hero-footnote">24 SELECTIONS <span aria-hidden="true">/</span> 9 COLLECTIONS <span aria-hidden="true">/</span> NATURAL CHARACTER</span></div><div class="hero-image"><img src="assets/enhanced-workshop.png" alt="Woven baskets stacked inside the Sri Balaji Bamboo Works workshop" fetchpriority="high"><span class="image-caption">FROM OUR WORKSHOP, TO YOUR EVERYDAY</span><div class="hero-seal" aria-hidden="true">WOVEN<br><em>with character</em></div></div></section><div class="material-strip"><span>ಬುಟ್ಟಿ · Butti</span><span aria-hidden="true">✳</span><span>ಮೊರ · Mara</span><span aria-hidden="true">✳</span><span>ಬಿದಿರು · Bamboo</span><span aria-hidden="true">✳</span><span>Made for the everyday</span></div>${collectionJourney()}<section class="section container featured">${sectionTitle('LITTLE DETAILS. LASTING CHARACTER.','Find your everyday.')}<div class="product-grid">${['biryani-basket','mara-small','bechanage'].map(id=>card(findProduct(id))).join('')}</div></section><section class="story-band"><div class="story-photo"><img src="assets/enhanced-workshop.png" loading="lazy" alt="Baskets and traditional woven forms in the workshop"><span class="image-caption">A GLIMPSE INSIDE THE WORKSHOP</span></div><div class="story-copy"><span class="eyebrow">THE MATERIAL & THE MAKING</span><h2>Every strip.<br><em>A little character.</em></h2><p>The colour of a bamboo strip. The rhythm of a herringbone weave. The curve of a familiar basket. Look closely and every form has its own texture.</p><p>Explore the actual collection, from household baskets and pooja trays to larger Makkari and bamboo materials.</p>${link('/story','Inside the collection','button button-sand')}</div></section>${bulkBand()}`;}

function shop(params){
 shopState={category:categories[params.get('category')]?params.get('category'):'',query:params.get('q')||'',sort:'featured'};
 const c=categoryInfo[shopState.category];
 return `<section class="page-heading container"><div class="breadcrumb"><a href="/">Home</a><span>/</span>Shop</div><span class="eyebrow">24 SELECTIONS · ENGLISH & KANNADA</span><h1>${c?c.name:'Useful forms.'}<br><em>${c?'Naturally distinctive.':'Beautifully woven.'}</em></h1>${c?`<p class="kn" lang="kn">${c.kn}</p><p>${c.description}</p>`:'<p>Explore baskets, traditional trays, hand fans and bamboo materials. Prices come directly from the workshop.</p>'}</section><section class="container shop-section"><div class="category-tabs" aria-label="Product categories">${[['','All products'],...Object.entries(categories)].map(([id,label])=>`<button data-category="${id}" aria-pressed="${shopState.category===id}">${label}</button>`).join('')}</div><div class="shop-layout"><aside class="shop-filters"><h2>Find your form.</h2><label for="collection-search">Search English / ಕನ್ನಡ</label><div class="search-input"><input id="collection-search" type="search" placeholder="Butti, Mara, ಬುಟ್ಟಿ…" value="${esc(shopState.query)}">${icon('search')}</div><div class="filter-note">${icon('leaf')}<p>Natural colour and weave vary. Confirm the measurements and finish that suit your purpose.</p></div><a href="/collections" class="text-link">About each collection ${arrow}</a><p class="small muted">Ranges remain ranges. A pair contains two pieces. Any unspecified price unit is confirmed on enquiry.</p></aside><div class="shop-results"><div class="results-toolbar"><p id="result-count" role="status"></p><label class="sort-label" for="sort">Sort by <select id="sort"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name: A–Z</option></select></label></div><div id="shop-grid" class="product-grid"></div><div id="shop-empty" hidden class="empty-state"><h2>No pieces found.</h2><p>Try an English or Kannada name, or explore every collection.</p><button class="button" data-clear-filters>Clear filters ${arrow}</button></div></div></div></section>${bulkBand()}`;
}

function updateShop(){
  const list=filterProducts(shopState);$('#shop-grid').innerHTML=list.map(card).join('');$('#result-count').textContent=`${list.length} ${list.length===1?'piece':'pieces'} in the collection`;$('#shop-empty').hidden=list.length>0;
  document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===shopState.category)));
}
function productPage(id){
 const p=findProduct(id);if(!p)return notFound();selectedSize=p.options[0];productQuantity=1;
 return `<div class="container"><div class="breadcrumb"><a href="/">Home</a><span>/</span><a href="/collections/${p.category}">${categoryInfo[p.category].short}</a><span>/</span>${p.name}</div><section class="product-layout"><div class="product-gallery"><div id="product-main-image" class="product-stage is-depth" data-depth>${photo(p)}</div><div class="view-controls" role="group" aria-label="Photo depth controls"><button type="button" class="view-mode" data-toggle-depth aria-pressed="true">3D photo: On</button><span class="view-angles"><button type="button" data-view-turn="-6" aria-label="Tilt photo left">↶</button><button type="button" data-reset-depth aria-label="Reset photo tilt">Reset</button><button type="button" data-view-turn="6" aria-label="Tilt photo right">↷</button></span></div><div class="gallery-thumbs"><button class="active" data-thumb="primary" data-product="${p.id}" aria-label="Show main product photograph" aria-pressed="true">${photo(p)}</button><button data-thumb="detail" data-product="${p.id}" aria-label="Zoom the weave in the same photograph" aria-pressed="false">${photo(p,'detail-thumb')}</button>${p.photos.map((f,i)=>`<button data-thumb="${f}" data-product="${p.id}" aria-label="Show workshop view ${i+1}" aria-pressed="false"><img src="assets/${f}" loading="lazy" alt="${esc(p.name)}, workshop view ${i+1}"></button>`).join('')}</div><p id="photo-caption" class="small muted">${p.representative?'Representative collection photo; confirm the exact small-basket design.':'Real product photography; selected main images have been enhanced for clarity.'} The 3D controls tilt the photograph.</p></div><div class="product-info"><a class="eyebrow" href="/collections/${p.category}">${categories[p.category]}</a><h1>${p.name}</h1><p class="kn product-kn" lang="kn">${p.nameKn}</p><p class="product-price">${priceLabel(p)}</p><p class="price-context">${p.unit==='pair'?'One quantity = one pair (two pieces).':p.unit==='foot'?'Price is per foot of ladder length. Enter the length below.':p.unit==='piece'?'Price is for one piece.':'Price unit and exact measurements will be confirmed with your enquiry.'}${p.price!==p.priceMax?' Final price within this range is confirmed for your chosen specification.':''}</p><p class="product-description">${p.description}</p><ul class="product-features">${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><fieldset class="size-selector"><legend>Your selection</legend><div>${p.options.map((v,i)=>`<label><input type="radio" name="size" value="${esc(v)}" ${i===0?'checked':''}><span>${v}</span></label>`).join('')}</div></fieldset>${p.unit==='foot'?'<div class="ladder-length"><label for="ladder-length">Ladder length in feet</label><input type="number" id="ladder-length" min="1" max="1000" step="0.5" placeholder="e.g. 8" required><p id="ladder-estimate" class="small" role="status">Enter a length to see your price range.</p></div>':''}<label class="quantity-label">Quantity ${p.unit==='pair'?'(pairs)':p.unit==='foot'?'(ladders)':''}</label><div class="purchase-row"><div class="quantity-control"><button data-product-qty="-1" aria-label="Decrease quantity">−</button><output id="product-qty" aria-label="Quantity">1</output><button data-product-qty="1" aria-label="Increase quantity">+</button></div><button class="button" data-add="${p.id}">${icon('bag')} Add to bag</button></div>${link('/bulk?product='+p.id,'Discuss your requirements','text-link')}<div class="product-accordions"><details open><summary>Form & material</summary><dl class="spec-list"><div><dt>Local name</dt><dd>${p.localName}</dd></div><div><dt>Form</dt><dd>${p.form}</dd></div><div><dt>Material</dt><dd>${p.material}</dd></div><div><dt>Measurements</dt><dd>Confirm with the workshop before ordering.</dd></div></dl></details><details><summary>Care guidance</summary><p>${p.care}</p></details><details><summary>Ordering & delivery</summary><p>Submit your selection for owner approval. We confirm specifications, availability, the price unit and delivery before your Confirm &amp; pay button opens in My orders. Payment receipt is verified manually.</p></details></div></div></section></div><section class="texture-band"><div>${photo(p)}</div><div><span class="eyebrow">LOOK A LITTLE CLOSER</span><h2>Texture you can<br><em>almost feel.</em></h2><p>${p.form}. Natural character, visible in every detail.</p></div></section><section class="section container">${sectionTitle('KEEP EXPLORING','More from the collection.')}<div class="product-grid">${products.filter(x=>x.id!==p.id&&x.category===p.category).concat(products.filter(x=>x.category!==p.category)).slice(0,3).map(card).join('')}</div></section>`;
}
const itemNote=item=>`${item.size}${item.lengthFeet?' · '+item.lengthFeet+' ft per ladder':''} · Qty ${item.quantity}${findProduct(item.id)?.unit==='pair'?' pairs':''}`;
const quoteLabel=items=>{const q=quoteTotals(items);return amountRange(q.low,q.high)+(q.pending?' + prices to confirm':'');};

function summary(button=true){return `<aside class="order-summary"><h2>Your estimate</h2><div class="summary-row"><span>Products</span><strong>${quoteLabel(cart)}</strong></div><div class="summary-row"><span>Delivery & any applicable charges</span><span>To confirm</span></div><p class="small muted">Owner-supplied prices. Ranges, unconfirmed units, specifications and delivery are finalised with the workshop.</p>${button?link('/checkout','Prepare order request'):''}<a class="text-link" href="/contact">Need a hand? ${arrow}</a></aside>`;}
function cartPage(){return `<section class="container section"><div class="breadcrumb"><a href="/">Home</a><span>/</span>Your bag</div><div class="section-title"><div><span class="eyebrow">YOUR EVERYDAY FINDS</span><h1>Your bag<span class="heading-dot">.</span></h1><p>${cartCount(cart)} selections · pairs are counted as pairs</p></div>${link('/shop','Continue exploring','text-link')}</div>${cart.length?`<div class="cart-layout"><div class="cart-items">${cart.map((item,i)=>{const p=findProduct(item.id);const q=lineQuote(item);return `<article class="cart-item"><a href="/product/${p.id}">${photo(p)}</a><div class="cart-item-details"><a class="product-title" href="/product/${p.id}">${p.name}</a><p class="kn" lang="kn">${p.nameKn}</p><p class="small muted">${itemNote(item)}</p><p>${priceLabel(p)}${!p.unit?' · unit to confirm':''}</p><button class="remove-button" data-remove="${i}">Remove<span class="sr-only"> ${p.name}</span></button></div><div class="quantity-control"><button data-cart-qty="${i}" data-delta="-1" aria-label="Decrease ${p.name} quantity">−</button><output>${item.quantity}</output><button data-cart-qty="${i}" data-delta="1" aria-label="Increase ${p.name} quantity">+</button></div><strong class="line-total">${amountRange(q.low,q.high)}</strong></article>`;}).join('')}</div>${summary()}</div>`:`<div class="empty-state">${icon('bag')}<h2>A little room for something natural.</h2><p>Find a basket, tray or hand fan that feels right for you.</p>${link('/shop','Explore the collection')}</div>`}</section>`;}

const field=(name,label,options={})=>`<div class="form-field ${options.full?'full':''}"><label for="${name}">${label}${options.required===false?' <span class="muted">(optional)</span>':''}</label>${options.textarea?`<textarea id="${name}" name="${name}" rows="4" ${options.required===false?'':'required'} placeholder="${esc(options.placeholder||'')}"></textarea>`:`<input id="${name}" name="${name}" type="${options.type||'text'}" ${options.required===false?'':'required'} ${options.autocomplete?`autocomplete="${options.autocomplete}"`:''} ${options.inputmode?`inputmode="${options.inputmode}"`:''} placeholder="${esc(options.placeholder||'')}" ${options.maxlength?`maxlength="${options.maxlength}"`:''}>`}<span class="field-error" id="error-${name}"></span></div>`;
function checkout(){if(!cart.length)return `<section class="section container empty-state"><h1>Your bag is empty.</h1><p>Add something to your bag before preparing an order request.</p>${link('/shop','Explore the collection')}</section>`;
  return `<section class="section container"><div class="breadcrumb"><a href="/cart">Your bag</a><span>/</span>Order request</div><span class="eyebrow">THE NEXT STEP</span><h1>Let’s make it <em>yours.</em></h1><p class="intro">Submit your request to the workshop. Once the owner approves your final total, My orders will show your Confirm &amp; pay button.</p><div class="checkout-layout"><form id="checkout-form" novalidate><div id="checkout-errors" class="error-summary" role="alert" tabindex="-1" hidden></div><section class="form-panel"><h2><span class="step-number">01</span> Your details</h2><div class="form-grid">${field('name','Full name',{autocomplete:'name',full:true})}${field('email','Email address',{type:'email',autocomplete:'email'})}${field('phone','Mobile number',{type:'tel',autocomplete:'tel',inputmode:'tel',placeholder:'10-digit mobile number'})}</div></section><section class="form-panel"><h2><span class="step-number">02</span> Delivery details</h2><div class="form-grid">${field('address','Street address',{autocomplete:'street-address',full:true})}${field('landmark','Landmark / apartment',{required:false,full:true})}${field('city','City',{autocomplete:'address-level2'})}${field('state','State',{autocomplete:'address-level1'})}${field('pincode','PIN code',{autocomplete:'postal-code',inputmode:'numeric',maxlength:6})}<div class="form-field"><label for="country">Country</label><input id="country" value="India" readonly></div>${field('notes','Anything else we should know?',{required:false,textarea:true,full:true})}</div></section><section class="form-panel"><h2><span class="step-number">03</span> Review & prepare</h2><p>This saves an order request on our server for owner review. You will see its status in My orders. Payment stays locked until the owner approves the final total.</p><p>After approval, choose Confirm &amp; pay in <a class="text-link" href="/orders">My orders</a>. UPI payment receipt is checked separately by the workshop.</p><button type="submit" class="button">Submit for owner approval ${arrow}</button><p class="small muted">Your contact and delivery details are sent to the workshop for this request. A private tracking key is saved in this browser; keep your tracking link safe.</p></section></form><div><div class="checkout-products">${cart.map(item=>{const p=findProduct(item.id);return `<div>${photo(p)}<span>${p.name}<small>${itemNote(item)} · ${priceLabel(p)}${!p.unit?' · unit to confirm':''}</small></span><strong>${amountRange(lineQuote(item).low,lineQuote(item).high)}</strong></div>`;}).join('')}</div>${summary(false)}</div></div></section>`;}
function story(){return `<section class="story-hero container"><div><span class="eyebrow">OUR STORY</span><h1>Bamboo, woven into<br><em>everyday life.</em></h1><p>Discover the baskets, trays and bamboo materials at Sri Balaji Bamboo Works.</p></div><img src="assets/enhanced-workshop.png" alt="Stacks of woven bamboo baskets in the workshop"></section><section class="editorial-section container"><div><span class="eyebrow">01 / THE MATERIAL</span><h2>A closer look<br><em>at bamboo.</em></h2><p>Warm tones. Distinctive texture. A material with a character of its own.</p><p>Split and woven into different patterns, bamboo takes on many forms across our collection — from rounded baskets to traditional winnowing trays.</p></div><div class="editorial-pair">${photo(products[5])}<img src="assets/enhanced-bamboo-yard.png" loading="lazy" alt="Natural bamboo stock in an outdoor yard"></div></section><section class="editorial-section reverse container"><div><span class="eyebrow">02 / THE COLLECTION</span><h2>Useful forms.<br><em>Distinctive weaves.</em></h2><p>Some pieces are open and airy. Others use a closer herringbone weave. Each brings a different texture to a familiar, useful form.</p>${link('/shop','Find your everyday essentials','text-link')}</div><div class="editorial-pair">${photo(products[0])}${photo(products[4])}</div></section><section class="closing-banner"><span class="eyebrow">MAKE ROOM FOR THE NATURAL</span><h2>Find a piece for<br><em>your everyday.</em></h2>${link('/shop','Explore the collection','button button-sand')}</section>${bulkBand()}`;}
function hasContact(){return !!(business.whatsapp||business.email);}
function enquiryForm(kind,params=new URLSearchParams()){
  return `<form id="enquiry-form" data-kind="${kind}"><div class="form-grid">${field('name','Your name',{autocomplete:'name'})}${kind==='bulk'?field('company','Business name',{autocomplete:'organization',required:false}):field('phone','Phone number',{autocomplete:'tel',type:'tel',required:false})}${field('email','Email address',{autocomplete:'email',type:'email',full:true})}${kind==='bulk'?field('phone','Phone number',{autocomplete:'tel',type:'tel',required:false}):''}<div class="form-field ${kind==='contact'?'full':''}"><label for="product">${kind==='bulk'?'Product type':'Enquiry type'}</label><select id="product" name="product"><option value="General enquiry">${kind==='bulk'?'Choose a product':'General enquiry'}</option>${products.map(p=>`<option ${params.get('product')===p.id?'selected':''} value="${p.name} / ${p.nameKn}">${p.name} / ${p.nameKn}</option>`).join('')}</select></div>${kind==='bulk'?field('quantity','Estimated quantity',{inputmode:'numeric',type:'number',required:false}):''}${kind==='bulk'?field('pincode','Delivery PIN code',{inputmode:'numeric',maxlength:6,required:false}):''}${field('message',kind==='bulk'?'Specifications / message':'Your message',{textarea:true,full:true,placeholder:kind==='bulk'?'Sizes, quantity, material or other requirements…':'How can we help?'})}</div><button class="button full-button" type="submit">Prepare enquiry ${arrow}</button><p class="small muted">${hasContact()?'Review your enquiry before sending through your chosen contact channel.':'Prepare and download your enquiry. Direct contact details will be available when confirmed.'}</p></form><div id="enquiry-result" class="enquiry-result" tabindex="-1" hidden></div>`;
}
function bulk(params){return `<section class="split-heading"><div><span class="eyebrow">BULK ORDERS & MATERIALS</span><h1>Bamboo for<br><em>your business.</em></h1><p>More pieces. Specific requirements. A project in mind.<br>Tell us what you’re looking for.</p><a href="#bulk-form" class="button" data-scroll="bulk-form">Discuss your requirements ${arrow}</a></div><img src="assets/enhanced-bamboo-yard.png" alt="Bamboo poles and ladder frames in an outdoor stockyard"></section><section class="container section bulk-categories"><div class="categories-grid">${categoryCard('butti','Butti · Baskets','Household & occasions.',0)}${categoryCard('mara','Mara · Trays','Four traditional selections.',12)}${categoryCard('koolu','Koolu · Bamboo','Poles, strips & ladders.',4)}</div></section><section id="bulk-form" class="container enquiry-layout section"><div><span class="eyebrow">WORK TOGETHER</span><h2>Let’s discuss<br><em>your requirements.</em></h2><p>Share a few details about what you need.</p><ol class="process-list"><li><span>01</span><div><h3>Share your requirements</h3><p>Product type, quantities, sizes and intended use.</p></div></li><li><span>02</span><div><h3>Confirm the details</h3><p>Discuss available options and delivery arrangements.</p></div></li><li><span>03</span><div><h3>Receive a quotation</h3><p>Final pricing and specifications for your requirements.</p></div></li></ol><img class="workshop-detail" src="assets/enhanced-tray-stock.png" alt="Stacks of woven trays in the workshop" loading="lazy"></div><div class="form-panel"><h2>Request a quotation</h2><p>Start with a few details. We’ll take it from there.</p>${enquiryForm('bulk',params)}</div></section>`;}
function contact(){return `<section class="container section"><span class="eyebrow">CONTACT SRI BALAJI BAMBOO WORKS</span><h1>Let’s talk <em>bamboo.</em></h1><p class="intro">A product question. A project idea. A larger order.<br>We’d love to hear what you have in mind.</p><div class="enquiry-layout contact-layout"><div><img class="contact-photo" src="assets/enhanced-workshop.png" alt="Baskets stacked at the workshop in natural light"><div class="contact-detail"><h2>Call or message</h2>${business.whatsapp?`<a href="https://wa.me/${business.whatsapp.replace(/\D/g,'')}" target="_blank" rel="noopener noreferrer">+91 95914 57484 · WhatsApp ${arrow}</a>`:'<p>Phone details coming soon.</p>'}</div><div class="contact-detail"><h2>Email</h2>${business.email?`<a href="mailto:${esc(business.email)}">${esc(business.email)}</a>`:'<p>Email details coming soon.</p>'}</div><div class="contact-detail"><h2>Visit the workshop</h2><p>${business.address?esc(business.address):'Workshop address to be confirmed.'}</p>${business.address?`<a class="text-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(business.address)}" target="_blank" rel="noopener noreferrer">View on map ${arrow}</a>`:''}</div></div><div class="form-panel"><h2>Send an enquiry</h2>${enquiryForm('contact')}<div class="contact-payment"><h3>Already have a confirmed total?</h3><p>The workshop approves your final total before your QR payment button opens. We verify receipt manually.</p>${link('/orders','View My orders','text-link')}</div></div></div></section>${bulkBand()}`;}
function payment(){return orderPage('payment');}
function care(){return `<section class="container section reading-page"><span class="eyebrow">A LITTLE GUIDANCE</span><h1>Made part of<br><em>your everyday.</em></h1><h2>Caring for natural bamboo</h2><p>Keep woven bamboo in a dry, ventilated place. Dust with a soft cloth or gentle brush. Avoid soaking and prolonged damp conditions. Let any lightly damp piece dry fully before storing.</p><h2>A note on natural variation</h2><p>Weave, colour and texture can differ between pieces. The collection uses workshop photos and an owner-supplied fan image, with selected photos enhanced for clarity. The Small Basket uses a labelled representative photo. Confirm the dimensions and finish before ordering.</p><h2>How ordering works</h2><ol><li>Explore the collection and add pieces to your bag.</li><li>Submit an order request with your delivery details.</li><li>Check My orders for owner approval and the final total, including delivery.</li><li>After approval, choose Confirm &amp; pay and use the merchant QR. Submit your UPI reference for manual receipt verification.</li></ol><p>Listed prices were supplied by the owner. Ranges and unconfirmed units are finalised for your chosen specification. You can pay externally using our <a href="/orders">My orders & payment</a><a href="/owner">Owner sign in</a> after the final total is confirmed. We verify receipt manually; this site does not confirm payment or an order automatically.</p><h2>Delivery & returns</h2><p>Please contact us to confirm delivery availability, charges, lead times and the return arrangements for your order before payment.</p><h2>Your details</h2><p>Your shopping bag is saved in this browser. Submitted order-request details are stored on the workshop server for owner review. Private tracking keys are saved in this browser. General enquiries are prepared on your device and shared only when you choose WhatsApp or email.</p>${link('/contact','Ask us a question')}</section>`;}
function notFound(){return `<section class="container section empty-state"><span class="eyebrow">A SMALL DETOUR</span><h1>This page wandered off.</h1><p>Let’s get you back to the collection.</p>${link('/shop','Explore the collection')}</section>`;}
let lastRequest=null;
try{lastRequest=JSON.parse(sessionStorage.getItem('sbb-request')||'null');}catch{}
function requestText(request){return `Sri Balaji Bamboo Works\n${request.kind==='order'?'ORDER REQUEST — PLEASE CONFIRM DETAILS':'ENQUIRY'}\nReference: ${request.reference}\n\n${Object.entries(request.details).filter(([,v])=>v).map(([k,v])=>`${k[0].toUpperCase()+k.slice(1)}: ${v}`).join('\n')}\n\n${request.items?request.items.map(item=>{const p=findProduct(item.id);const q=lineQuote(item);return `${p.name} / ${p.nameKn}\n${itemNote(item)} · ${priceLabel(p)}${!p.unit?' (price unit to confirm)':''}\nEstimated line: ${amountRange(q.low,q.high)}`;}).join('\n\n')+`\n\nEstimated products: ${quoteLabel(request.items)}\nPlease confirm the selected specifications, price units, availability and delivery charges. No payment taken.`:''}`;}

function shareActions(request){const text=requestText(request);return `<div class="request-actions">${business.whatsapp?`<a class="button" href="https://wa.me/${business.whatsapp.replace(/\D/g,'')}?text=${encodeURIComponent(text)}" target="_blank" rel="noopener noreferrer">Send via WhatsApp ${arrow}</a>`:''}${business.email?`<a class="button button-outline" href="mailto:${esc(business.email)}?subject=${encodeURIComponent('Enquiry '+request.reference)}&body=${encodeURIComponent(text)}">Send by email ${arrow}</a>`:''}<button class="button ${hasContact()?'button-outline':''}" data-download-request>Download request ${arrow}</button></div>`;}
function requestPage(){if(!lastRequest)return notFound();return `<section class="container section request-page"><div class="request-check">${icon('check')}</div><span class="eyebrow">YOUR SELECTION, ALL TOGETHER</span><h1>Your request is <em>ready.</em></h1><p>Reference ${esc(lastRequest.reference)}</p><div class="request-notice"><strong>Prepared on this device. Not yet sent.</strong><p>${hasContact()?'Use one of the contact options below to send your request.':'Download your request to keep your selection. Contact channels will be available once the business details are confirmed.'} Your order is confirmed only after you agree the details with the business.</p></div><pre class="request-preview">${esc(requestText(lastRequest))}</pre>${shareActions(lastRequest)}${lastRequest.kind==='order'?'<div class="request-notice"><strong>Pay only after your total is confirmed.</strong><p>Once the workshop confirms the exact amount, <a href="/payment">view our UPI payment QR</a>. Payment receipt is checked manually.</p></div>':''}${link('/shop','Continue exploring','text-link')}</section>`;}
function downloadRequest(){if(!lastRequest)return;const blob=new Blob([requestText(lastRequest)],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=lastRequest.reference+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Your request has been downloaded.');}
function render(){
  const legacy=location.hash.startsWith('#/');const [pathname,query='']=(legacy?location.hash.slice(1):(location.pathname+location.search)).split('?');const params=new URLSearchParams(query);if(legacy){const safeParams=new URLSearchParams(query);safeParams.delete('access');history.replaceState(null,'',pathname+(safeParams.size?'?'+safeParams:''));}
  const routes={'/':()=>home(),'/shop':()=>shop(params),'/collections':collections,'/cart':cartPage,'/checkout':checkout,'/story':story,'/bulk':()=>bulk(params),'/contact':contact,'/payment':payment,'/orders':()=>orderPage('orders'),'/owner':()=>orderPage('owner'),'/care':care,'/request':requestPage};
  const titles={'/':'Bamboo Shop in Shidlaghatta','/shop':'Bamboo baskets, trays & materials','/collections':'Nine collections','/cart':'Your bag','/checkout':'Order request','/story':'Our bamboo workshop in Shidlaghatta','/bulk':'Bulk orders','/contact':'Contact our Shidlaghatta bamboo shop','/payment':'UPI payment','/orders':'My orders','/owner':'Owner inbox','/care':'Care & ordering','/request':'Your request'};
  const isProduct=pathname.startsWith('/product/');const product=isProduct?findProduct(pathname.split('/')[2]):null;
  const family=pathname.match(/^\/collections\/([a-z-]+)$/)?.[1];if(family&&categoryInfo[family]){routes[pathname]=()=>shop(new URLSearchParams({category:family}));titles[pathname]=categoryInfo[family].name;}
  $('#main').innerHTML=isProduct?productPage(pathname.split('/')[2]):(routes[pathname]||notFound)();renderHeader();renderFooter();
  document.title=`${product?.name||titles[pathname]||'Page not found'} | Sri Balaji Bamboo Works`;const description=document.querySelector('meta[name=description]');if(description)description.content=product?product.description:family&&categoryInfo[family]?categoryInfo[family].description:'Bamboo shop in Shidlaghatta, Chikkaballapur, Karnataka. Explore baskets, Mara trays, hand fans, bamboo poles and ladders at Sri Balaji Bamboo Works.';for(const [property,value] of Object.entries({'og:title':document.title,'og:description':description?.content||'','og:url':business.website+pathname})){const meta=document.querySelector('meta[property="'+property+'"]');if(meta)meta.content=value;}const robots=document.querySelector('meta[name=robots]');if(robots)robots.content=['/owner','/orders','/cart','/checkout','/payment','/request'].includes(pathname)?'noindex, nofollow':'index, follow';const canonical=document.querySelector('link[rel=canonical]');if(canonical)canonical.href=business.website+pathname;
  if(pathname==='/shop'||(family&&categoryInfo[family]))updateShop();
  syncPhotoDepthPreference();setupMotion();mountOrders(pathname,params);
  window.scrollTo({top:0,behavior:'instant'});const heading=$('#main h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}
}
document.addEventListener('click',event=>{
  const target=event.target.closest('button,a');if(!target)return;
  if(target.hasAttribute('data-toggle-depth')){
    const stage=$('#product-main-image');const enabled=target.getAttribute('aria-pressed')!=='true';
    resetPhotoDepth(stage);stage.classList.toggle('is-depth',enabled);stage.toggleAttribute('data-depth',enabled);target.setAttribute('aria-pressed',String(enabled));target.textContent=enabled?'3D view: On':'3D view: Off';
    document.querySelectorAll('[data-view-turn],[data-reset-depth]').forEach(b=>b.disabled=!enabled);return;
  }
  if(target.hasAttribute('data-view-turn')){
    const stage=$('#product-main-image');const current=parseFloat(stage.style.getPropertyValue('--tilt-y'))||0;
    stage.style.setProperty('--tilt-y',Math.min(12,Math.max(-12,current+Number(target.dataset.viewTurn)))+'deg');return;
  }
  if(target.hasAttribute('data-reset-depth')){resetPhotoDepth($('#product-main-image'));return;}
  if(target.hasAttribute('data-skip')){event.preventDefault();$('#main').focus();return;}
  if(target.hasAttribute('data-search')){$('#search-dialog').showModal();return;}
  if(target.hasAttribute('data-close-dialog')){$('#search-dialog').close();return;}
  if(target.hasAttribute('data-menu')){const nav=$('#mobile-nav');nav.hidden=!nav.hidden;target.setAttribute('aria-expanded',String(!nav.hidden));return;}
  if(target.hasAttribute('data-category')){location.hash='/shop'+(target.dataset.category?'?category='+target.dataset.category:'');return;}
  if(target.hasAttribute('data-clear-filters')){shopState={category:'',query:'',sort:'featured'};$('#collection-search').value='';$('#sort').value='featured';updateShop();return;}
  if(target.dataset.scroll){event.preventDefault();const destination=document.getElementById(target.dataset.scroll);destination?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});if(destination?.matches('input,select,textarea'))destination.focus({preventScroll:true});return;}
  if(target.hasAttribute('data-thumb')){
    const p=findProduct(target.dataset.product);const detail=target.dataset.thumb==='detail';const original=!['primary','detail'].includes(target.dataset.thumb);$('#product-main-image').innerHTML=detail?photo(p,'weave-detail'):original?`<img class="original-product-image" src="assets/${target.dataset.thumb}" alt="${p.name}, original workshop photograph">`:photo(p);
    $('#photo-caption').textContent=detail?'Close-up from the same product photograph.':original?'Workshop photograph. Product colour and weave may vary.':'Workshop photo · Cropped to focus on the product. Use the controls to tilt the photo.';
    document.querySelectorAll('[data-thumb]').forEach(b=>{b.classList.toggle('active',b===target);b.setAttribute('aria-pressed',String(b===target));});return;
  }
  if(target.hasAttribute('data-product-qty')){productQuantity=Math.min(99,Math.max(1,productQuantity+Number(target.dataset.productQty)));$('#product-qty').textContent=productQuantity;updateLadderEstimate();return;}
  if(target.dataset.add){const p=findProduct(target.dataset.add);let lengthFeet=null;if(p.unit==='foot'){const input=$('#ladder-length');if(!input.reportValidity()||!input.value)return;lengthFeet=Number(input.value);}cart=normalizeCart([...cart,{id:p.id,size:selectedSize,quantity:productQuantity,lengthFeet}]);persistCart();setupMotion();notify(`${p.name} added to your bag.`);return;}
  if(target.hasAttribute('data-cart-qty')){const item=cart[Number(target.dataset.cartQty)];item.quantity+=Number(target.dataset.delta);cart=normalizeCart(cart);persistCart();const focusLabel=target.getAttribute('aria-label');render();const replacement=[...document.querySelectorAll('[data-cart-qty]')].find(x=>x.getAttribute('aria-label')===focusLabel);replacement?.focus();return;}
  if(target.hasAttribute('data-remove')){cart.splice(Number(target.dataset.remove),1);persistCart();render();notify('Item removed from your bag.');return;}
  if(target.hasAttribute('data-download-request'))downloadRequest();
  const href=target.getAttribute('href');if(target.tagName==='A'&&href?.startsWith('/')&&!href.startsWith('//')&&!target.hasAttribute('download')&&!target.target&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey&&!event.altKey){event.preventDefault();history.pushState(null,'',href);resetPhotoDepth(activeDepthCard);render();}
});
function updateLadderEstimate(){const input=$('#ladder-length');if(!input)return;const length=Number(input.value);const ladder=findProduct('bamboo-ladder');$('#ladder-estimate').textContent=input.value&&input.validity.valid?`${productQuantity} × ${length} ft: ${amountRange(length*productQuantity*ladder.price,length*productQuantity*ladder.priceMax)}`:'Enter a valid length (1–1000 feet, in half-foot increments).';}
document.addEventListener('input',event=>{if(event.target.id==='collection-search'){shopState.query=event.target.value;updateShop();}if(event.target.id==='ladder-length')updateLadderEstimate();});
document.addEventListener('change',event=>{if(event.target.id==='sort'){shopState.sort=event.target.value;updateShop();}if(event.target.name==='size')selectedSize=event.target.value;});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('#mobile-nav')&&!$('#mobile-nav').hidden){$('#mobile-nav').hidden=true;$('[data-menu]').setAttribute('aria-expanded','false');$('[data-menu]').focus();}});
document.addEventListener('submit',async event=>{
  if(event.target.id==='search-form'){event.preventDefault();const q=new FormData(event.target).get('q');$('#search-dialog').close();location.hash='/shop?q='+encodeURIComponent(q);return;}
  if(event.target.id==='checkout-form'){
    event.preventDefault();if(!cart.length){location.hash='/cart';return;}
    const form=event.target;const details=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,String(v).trim()]));const errors=validateCheckout(details);
    form.querySelectorAll('[aria-invalid]').forEach(f=>{f.removeAttribute('aria-invalid');f.removeAttribute('aria-describedby');});form.querySelectorAll('.field-error').forEach(e=>e.textContent='');
    if(Object.keys(errors).length){for(const [key,message] of Object.entries(errors)){const input=form.elements[key];input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby','error-'+key);$('#error-'+key).textContent=message;}const box=$('#checkout-errors');box.hidden=false;box.innerHTML=`<strong>Please check your details.</strong><ul>${Object.keys(errors).map(k=>`<li><a href="#${k}" data-scroll="${k}">${esc(form.querySelector(`label[for="${k}"]`).textContent)}: ${errors[k]}</a></li>`).join('')}</ul>`;box.focus();return;}
    const submit=form.querySelector('button[type="submit"]');if(submit.disabled)return;submit.disabled=true;submit.textContent='Submitting request…';try{await placeOrder(details,cart.map(x=>({...x})));location.hash='/orders';}catch(error){const box=$('#checkout-errors');if(box){box.hidden=false;box.textContent=error.message;box.focus();}}finally{submit.disabled=false;submit.textContent='Submit for owner approval →';}return;
  }
  if(event.target.id==='enquiry-form'){
    event.preventDefault();const form=event.target;if(!form.reportValidity())return;
    const details=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,String(v).trim()]));if(details.quantity&&(!Number.isInteger(Number(details.quantity))||Number(details.quantity)<1)){form.elements.quantity.setCustomValidity('Enter a whole quantity greater than zero.');form.elements.quantity.reportValidity();form.elements.quantity.addEventListener('input',()=>form.elements.quantity.setCustomValidity(''),{once:true});return;}
    lastRequest={kind:'enquiry',reference:'SBB-'+crypto.randomUUID().slice(0,8).toUpperCase(),details};
    const result=$('#enquiry-result');result.hidden=false;result.innerHTML=`<span class="eyebrow">READY TO SHARE</span><h3>Your enquiry is prepared.</h3><p>It has not been sent yet. ${hasContact()?'Choose a contact option below to send it.':'Download it to keep your requirements together.'}</p><pre class="request-preview">${esc(requestText(lastRequest))}</pre>${shareActions(lastRequest)}`;result.focus();result.scrollIntoView({block:'center',behavior:'instant'});
  }
});
let depthFrame=0;
let activeDepthCard=null;
let activeDepthBounds=null;
const reducedPhotoMotion=matchMedia('(prefers-reduced-motion: reduce)');
document.addEventListener('click',event=>{if(event.target.closest('[data-motion]'))syncPhotoDepthPreference();});
const finePhotoPointer=matchMedia('(hover: hover) and (pointer: fine)');
function resetPhotoDepth(card){
  cancelAnimationFrame(depthFrame);
  if(card)for(const property of ['--tilt-x','--tilt-y','--light-x','--light-y'])card.style.removeProperty(property);
  if(card===activeDepthCard){activeDepthCard=null;activeDepthBounds=null;}
}
document.addEventListener('pointermove',event=>{
  if(!motionEnabled()||!finePhotoPointer.matches)return;
  const card=event.target.closest?.('[data-depth]');if(!card)return;
  if(activeDepthCard!==card){resetPhotoDepth(activeDepthCard);activeDepthCard=card;activeDepthBounds=card.getBoundingClientRect();}
  const bounds=activeDepthBounds;
  const x=Math.max(0,Math.min(1,(event.clientX-bounds.left)/bounds.width));
  const y=Math.max(0,Math.min(1,(event.clientY-bounds.top)/bounds.height));
  cancelAnimationFrame(depthFrame);depthFrame=requestAnimationFrame(()=>{
    card.style.setProperty('--tilt-x',((.5-y)*9).toFixed(2)+'deg');
    card.style.setProperty('--tilt-y',((x-.5)*11).toFixed(2)+'deg');
    card.style.setProperty('--light-x',(x*100).toFixed(1)+'%');card.style.setProperty('--light-y',(y*100).toFixed(1)+'%');
  });
},{passive:true});
document.addEventListener('pointerout',event=>{
  const card=event.target.closest?.('[data-depth]');if(card&&!card.contains(event.relatedTarget))resetPhotoDepth(card);
});
function syncPhotoDepthPreference(){
  const toggle=$('[data-toggle-depth]');const stage=$('#product-main-image');if(!toggle||!stage)return;
  if(!motionEnabled()){
    resetPhotoDepth(stage);stage.classList.remove('is-depth');stage.removeAttribute('data-depth');toggle.disabled=true;toggle.setAttribute('aria-pressed','false');toggle.textContent='Reduced motion';
    document.querySelectorAll('[data-view-turn],[data-reset-depth]').forEach(b=>b.disabled=true);
  }else if(toggle.disabled){
    toggle.disabled=false;toggle.setAttribute('aria-pressed','true');toggle.textContent='3D view: On';stage.classList.add('is-depth');stage.setAttribute('data-depth','');
    document.querySelectorAll('[data-view-turn],[data-reset-depth]').forEach(b=>b.disabled=false);
  }
}
reducedPhotoMotion.addEventListener('change',()=>{if(reducedPhotoMotion.matches)resetPhotoDepth(activeDepthCard);syncPhotoDepthPreference();});
window.addEventListener('popstate',()=>{resetPhotoDepth(activeDepthCard);render();});
window.addEventListener('hashchange',()=>{resetPhotoDepth(activeDepthCard);render();});
window.addEventListener('storage',event=>{if(event.key==='sbb-cart'){try{cart=normalizeCart(JSON.parse(event.newValue||'[]'));}catch{cart=[];}renderHeader();setupMotion();if(['/cart','/checkout'].includes(location.pathname))render();}});
setupOrderEvents();
render();
